<?php
/**
 * Página de ajustes del plugin en el panel de WordPress.
 * Incluye configuración de GTM y GA4 directamente, sin depender de plugins externos.
 */

if (!defined('ABSPATH')) exit;

add_action('admin_menu', function () {
    add_menu_page(
        'Rabbit Consent',
        'Rabbit Consent',
        'manage_options',
        'smart-consent',
        'smart_consent_settings_page',
        'data:image/svg+xml;base64,'
    );
});

function smart_consent_settings_page() {
    $gtm_id = trim(get_option('smart_gtm_id', ''));
    $ga4_id = trim(get_option('smart_ga4_id', ''));
    ?>
    <div class="wrap">
        <h1>Rabbit Consent Settings</h1>

        <?php if (empty($gtm_id) && empty($ga4_id)) : ?>
        <div class="notice notice-warning">
            <p><strong>Atención:</strong> No has configurado ningún destino de analítica.
            Introduce un <strong>GTM Container ID</strong> (recomendado) o un <strong>GA4 Measurement ID</strong>
            en la sección "Integración con Google" para que los eventos se envíen correctamente.</p>
        </div>
        <?php elseif (!empty($gtm_id) && !empty($ga4_id)) : ?>
        <div class="notice notice-warning">
            <p><strong>Atención:</strong> Tienes configurados tanto GTM como GA4. Cuando ambos están
            presentes, <strong>GTM tiene prioridad</strong> y GA4 directo se ignora. Configura GA4 como
            etiqueta dentro de GTM y deja vacío el campo GA4 Measurement ID si no lo necesitas por separado.</p>
        </div>
        <?php else : ?>
        <div class="notice notice-success is-dismissible">
            <p>
            <?php if (!empty($gtm_id)) : ?>
                <strong>GTM activo:</strong> Los eventos se envían vía Google Tag Manager (<code><?php echo esc_html($gtm_id); ?></code>).
                Asegúrate de tener la etiqueta de GA4 configurada dentro de GTM.
            <?php else : ?>
                <strong>GA4 directo activo:</strong> Los eventos se envían directamente a Google Analytics 4 (<code><?php echo esc_html($ga4_id); ?></code>).
            <?php endif; ?>
            </p>
        </div>
        <?php endif; ?>

        <form method="post" action="options.php">
            <?php
            settings_fields('smart_consent_group');
            do_settings_sections('smart-consent');
            submit_button();
            ?>
        </form>
    </div>
    <?php
}

add_action('admin_init', function () {

    // Registrar todas las opciones
    $options = [
        'smart_gtm_id',
        'smart_ga4_id',
        'smart_enable_analytics',
        'smart_enable_ads',
        'smart_banner_text',
        'smart_banner_links',
        'smart_debug_mode',
        'smart_banner_bg_color',
        'smart_banner_text_color',
        'smart_banner_font_family',
        'smart_btn_accept_bg',
        'smart_btn_accept_text',
        'smart_btn_reject_bg',
        'smart_btn_reject_text',
        'smart_trigger_position',
        'smart_trigger_bg',
        'smart_trigger_icon_color',
        'smart_banner_icon_color',
        'smart_btn_accept_hover_bg',
        'smart_btn_accept_hover_text',
        'smart_btn_reject_hover_bg',
        'smart_btn_reject_hover_text',
        'smart_trigger_hover_bg',
        'smart_trigger_hover_icon_color',
        'smart_banner_icon',
    ];
    foreach ($options as $opt) {
        register_setting('smart_consent_group', $opt);
    }

    //Integración con Google
    add_settings_section(
        'smart_tracking_section',
        'Integración con Google',
        function () {
            echo "<p>Introduce <strong>GTM Container ID</strong> (ej. <code>GTM-XXXXXXX</code>) para usar Google Tag Manager
            — recomendado si ya tienes GTM configurado en tu cuenta —, o bien el <strong>GA4 Measurement ID</strong>
            (ej. <code>G-XXXXXXXXXX</code>) para enviar eventos directamente a Google Analytics 4 sin GTM.<br>
            <em>Si introduces ambos, GTM tiene prioridad y GA4 directo se ignora.</em></p>";
        },
        'smart-consent'
    );

    add_settings_field(
        'smart_gtm_id',
        'GTM Container ID',
        function () {
            $value = get_option('smart_gtm_id', '');
            echo "<input type='text' name='smart_gtm_id' value='" . esc_attr($value) . "'
                  placeholder='GTM-XXXXXXX' class='regular-text' />";
            echo "<p class='description'>El snippet de GTM se inyectará automáticamente. No necesitas instalar ningún otro plugin.</p>";
        },
        'smart-consent',
        'smart_tracking_section'
    );

    add_settings_field(
        'smart_ga4_id',
        'GA4 Measurement ID',
        function () {
            $value = get_option('smart_ga4_id', '');
            echo "<input type='text' name='smart_ga4_id' value='" . esc_attr($value) . "'
                  placeholder='G-XXXXXXXXXX' class='regular-text' />";
            echo "<p class='description'>Solo se usa si el campo GTM Container ID está vacío.
                  En este modo los eventos se envían directamente a GA4.</p>";
        },
        'smart-consent',
        'smart_tracking_section'
    );

    //Configuración General
    add_settings_section('smart_main_section', 'Configuración General', null, 'smart-consent');

    add_settings_field(
        'smart_enable_analytics', 'Activar Analytics (Consent Mode)',
        function () {
            $value = get_option('smart_enable_analytics');
            echo "<input type='checkbox' name='smart_enable_analytics' value='1' " . checked(1, $value, false) . " />";
            echo "<p class='description'>Habilita las señales de <code>analytics_storage</code> en Consent Mode v2.</p>";
        },
        'smart-consent', 'smart_main_section'
    );

    add_settings_field(
        'smart_enable_ads', 'Activar Ads (Consent Mode)',
        function () {
            $value = get_option('smart_enable_ads');
            echo "<input type='checkbox' name='smart_enable_ads' value='1' " . checked(1, $value, false) . " />";
            echo "<p class='description'>Habilita las señales de <code>ad_storage</code> en Consent Mode v2.</p>";
        },
        'smart-consent', 'smart_main_section'
    );

    add_settings_field(
        'smart_banner_text', 'Texto del banner',
        function () {
            $value = get_option('smart_banner_text', '');
            echo "<textarea name='smart_banner_text' rows='3' cols='50' placeholder='Usamos cookies para mejorar la experiencia.'>" . esc_textarea($value) . "</textarea>";
            echo "<p class='description'>Si se deja vacío se usará el texto por defecto. Puedes usar HTML básico.</p>";
        },
        'smart-consent', 'smart_main_section'
    );

    add_settings_field(
        'smart_banner_links', 'Links del banner',
        function () {
            $raw   = get_option('smart_banner_links', '');
            $links = [];
            if (!empty($raw)) {
                $decoded = json_decode($raw, true);
                if (is_array($decoded)) $links = $decoded;
            }
            if (empty($links)) {
                $links = [['label' => '', 'url' => '']];
            }
            echo "<div id='scp-links-wrapper'>";
            foreach ($links as $i => $link) {
                echo "<div class='scp-link-row' style='display:flex;gap:8px;align-items:center;margin-bottom:6px;'>";
                echo "<input type='text' class='scp-link-label' placeholder='Etiqueta (ej. Política de cookies)' value='" . esc_attr($link['label']) . "' style='width:210px;' />";
                echo "<input type='url' class='scp-link-url' placeholder='https://tudominio.com/politica-cookies' value='" . esc_attr($link['url']) . "' style='width:280px;' />";
                echo "<button type='button' class='button scp-remove-link' title='Eliminar fila'>&#x2715;</button>";
                echo "</div>";
            }
            echo "</div>";
            echo "<button type='button' class='button' id='scp-add-link'>+ A&#241;adir link</button>";
            echo "<input type='hidden' name='smart_banner_links' id='scp-links-json' value='" . esc_attr($raw) . "' />";
            echo "<p class='description'>Los links aparecerán en la parte inferior izquierda del banner (ej. Política de cookies, Política de privacidad).</p>";
            ?>
            <script>
            (function () {
                var wrapper   = document.getElementById('scp-links-wrapper');
                var addBtn    = document.getElementById('scp-add-link');
                var jsonInput = document.getElementById('scp-links-json');

                function addRow(label, url) {
                    var row = document.createElement('div');
                    row.className = 'scp-link-row';
                    row.style.cssText = 'display:flex;gap:8px;align-items:center;margin-bottom:6px;';
                    row.innerHTML = '<input type="text" class="scp-link-label" placeholder="Etiqueta (ej. Política de cookies)" value="' + (label||'') + '" style="width:210px;" />'
                                  + '<input type="url" class="scp-link-url" placeholder="https://tudominio.com/politica-cookies" value="' + (url||'') + '" style="width:280px;" />'
                                  + '<button type="button" class="button scp-remove-link" title="Eliminar fila">&#x2715;</button>';
                    wrapper.appendChild(row);
                }

                addBtn.addEventListener('click', function () { addRow('', ''); });

                wrapper.addEventListener('click', function (e) {
                    if (e.target.classList.contains('scp-remove-link')) {
                        e.target.closest('.scp-link-row').remove();
                    }
                });

                document.querySelector('form').addEventListener('submit', function () {
                    var rows  = wrapper.querySelectorAll('.scp-link-row');
                    var links = [];
                    rows.forEach(function (row) {
                        var label = row.querySelector('.scp-link-label').value.trim();
                        var url   = row.querySelector('.scp-link-url').value.trim();
                        if (label || url) links.push({ label: label, url: url });
                    });
                    jsonInput.value = JSON.stringify(links);
                });
            })();
            </script>
            <?php
        },
        'smart-consent', 'smart_main_section'
    );

    add_settings_field(
        'smart_debug_mode', 'Modo debug (consola)',
        function () {
            $value = get_option('smart_debug_mode');
            echo "<input type='checkbox' name='smart_debug_mode' value='1' " . checked(1, $value, false) . " />";
            echo "<p class='description'>Muestra mensajes en la consola del navegador para depuración.</p>";
        },
        'smart-consent', 'smart_main_section'
    );

    //Personalización del Banner
    add_settings_section(
        'smart_banner_design_section',
        'Personalización del Banner',
        function () {
            echo "<p>Personaliza los colores y tipografía del banner de cookies.</p>";
        },
        'smart-consent'
    );

    // Helper para renderizar campos de color con wp-color-picker
    $color_field = function ($option, $default) {
        $value = get_option($option, $default);
        echo "<input type='text'
                     name='" . esc_attr($option) . "'
                     value='" . esc_attr($value) . "'
                     class='scp-color-picker'
                     data-default-color='" . esc_attr($default) . "' />";
    };

    add_settings_field('smart_banner_bg_color', 'Fondo del banner',
        function () use ($color_field) { $color_field('smart_banner_bg_color', '#ffffff'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_banner_text_color', 'Color del texto',
        function () use ($color_field) { $color_field('smart_banner_text_color', '#333333'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field(
        'smart_banner_font_family', 'Tipografía',
        function () {
            $value   = get_option('smart_banner_font_family', '');
            $options = [
                ''             => 'Por defecto (sistema)',
                'Arial'        => 'Arial',
                'Georgia'      => 'Georgia',
                'Verdana'      => 'Verdana',
                'Trebuchet MS' => 'Trebuchet MS',
                'Roboto'       => 'Roboto (Google Fonts)',
                'Open Sans'    => 'Open Sans (Google Fonts)',
                'Lato'         => 'Lato (Google Fonts)',
                'Montserrat'   => 'Montserrat (Google Fonts)',
                'Poppins'      => 'Poppins (Google Fonts)',
            ];
            echo "<select name='smart_banner_font_family'>";
            foreach ($options as $font => $label) {
                echo "<option value='" . esc_attr($font) . "' " . selected($value, $font, false) . ">$label</option>";
            }
            echo "</select>";
            echo "<p class='description'>Las fuentes de Google Fonts se cargan automáticamente.</p>";
        },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_accept_bg', 'Botón Aceptar — fondo',
        function () use ($color_field) { $color_field('smart_btn_accept_bg', '#0073aa'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_accept_text', 'Botón Aceptar — texto',
        function () use ($color_field) { $color_field('smart_btn_accept_text', '#ffffff'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_accept_hover_bg', 'Botón Aceptar — fondo (hover)',
        function () use ($color_field) { $color_field('smart_btn_accept_hover_bg', '#005a87'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_accept_hover_text', 'Botón Aceptar — texto (hover)',
        function () use ($color_field) { $color_field('smart_btn_accept_hover_text', '#ffffff'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_reject_bg', 'Botón Rechazar — fondo',
        function () use ($color_field) { $color_field('smart_btn_reject_bg', '#ffffff'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_reject_text', 'Botón Rechazar — texto',
        function () use ($color_field) { $color_field('smart_btn_reject_text', '#0073aa'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_reject_hover_bg', 'Botón Rechazar — fondo (hover)',
        function () use ($color_field) { $color_field('smart_btn_reject_hover_bg', '#f0f0f0'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_btn_reject_hover_text', 'Botón Rechazar — texto (hover)',
        function () use ($color_field) { $color_field('smart_btn_reject_hover_text', '#0073aa'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field(
        'smart_trigger_position', 'Posición del botón de galleta',
        function () {
            $value = get_option('smart_trigger_position', 'left');
            echo "<select name='smart_trigger_position'>";
            echo "<option value='left'"  . selected($value, 'left',  false) . ">Abajo a la izquierda</option>";
            echo "<option value='right'" . selected($value, 'right', false) . ">Abajo a la derecha</option>";
            echo "</select>";
            echo "<p class='description'>Elige en qué esquina aparece el botón flotante con el icono de galleta.</p>";
        },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_trigger_bg', 'Botón galleta — color de fondo',
        function () use ($color_field) { $color_field('smart_trigger_bg', '#0073aa'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_trigger_icon_color', 'Botón galleta — color del icono',
        function () use ($color_field) { $color_field('smart_trigger_icon_color', '#ffffff'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_trigger_hover_bg', 'Botón galleta — fondo (hover)',
        function () use ($color_field) { $color_field('smart_trigger_hover_bg', '#005a87'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_trigger_hover_icon_color', 'Botón galleta — color del icono (hover)',
        function () use ($color_field) { $color_field('smart_trigger_hover_icon_color', '#ffffff'); },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field(
        'smart_banner_icon', 'Icono del banner y botón',
        function () {
            $value = get_option('smart_banner_icon', 'rabbit');
            echo "<select name='smart_banner_icon'>
                <option value='rabbit'" . selected($value, 'rabbit', false) . ">Conejo (White Rabbit)</option>
                <option value='dactilar'" . selected($value, 'dactilar', false) . ">Dactilar (huella)</option>
            </select>";
            echo "<p class='description'>Elige el icono que aparece en el botón flotante y en la cabecera del banner.</p>";
        },
        'smart-consent', 'smart_banner_design_section'
    );

    add_settings_field('smart_banner_icon_color', 'Icono cookie en el banner — color',
        function () use ($color_field) { $color_field('smart_banner_icon_color', '#4a1050'); },
        'smart-consent', 'smart_banner_design_section'
    );
});

// Cargar wp-color-picker solo en la página de ajustes del plugin
add_action('admin_enqueue_scripts', function ($hook) {
    if ($hook !== 'toplevel_page_smart-consent') return;

    wp_enqueue_style('wp-color-picker');
    wp_enqueue_script(
        'scp-color-picker-init',
        plugin_dir_url(dirname(__FILE__)) . 'public/js/admin-color-picker.js',
        ['wp-color-picker'],
        '3.0',
        true
    );
});
